import java.util.*;

public class Permutations {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        boolean[] used = new boolean[nums.length];
        backtrack(nums, new ArrayList<>(), used, result);
        return result;
    }

    private void backtrack(int[] nums, List<Integer> path,
                           boolean[] used, List<List<Integer>> result) {
        // 结束条件：每一位都已确定
        if (path.size() == nums.length) {
            result.add(new ArrayList<>(path));  // 必须拷贝
            return;
        }

        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;               // 跳过已在排列中的数字

            // 做选择
            path.add(nums[i]);
            used[i] = true;
            // 递归到下一位
            backtrack(nums, path, used, result);
            // 撤销选择（回溯）
            path.remove(path.size() - 1);
        used[i] = false;
        }
    }
}

import java.util.*;

public class PermutationsSwap {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        int[] arr = nums.clone(); // 拷贝，不改原数组
        backtrack(arr, 0, result);
        return result;
    }

    private void backtrack(int[] arr, int k, List<List<Integer>> result) {
        if (k == arr.length) {
            List<Integer> perm = new ArrayList<>();
            for (int v : arr) perm.add(v);
            result.add(perm);
            return;
        }
        for (int i = k; i < arr.length; i++) {
            swap(arr, k, i);          // 第 k 位选 arr[i]
            backtrack(arr, k + 1, result);
            swap(arr, k, i);          // 撤销
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}
